                        <span style="top: -3px;right: auto;left: 20px;" v-if="auth.linked.length && badge.totalUserBadge(user.id) && auth.activeUser.id !== user.id" class="side-notification">{{ badgeFilter(badge.totalUserBadge(user.id))}}</span> 
