<script setup>
import { onMounted, ref, watch } from 'vue';
import UserIcon from '../Board/Mixed/UserIcon.vue';
import GlowdNews from './GlowdNews.vue'
import { useAuthUserStore } from '@/store/auth'
import { computed } from 'vue';
import { useRoute } from 'vue-router';
import { useSideMenuView } from '@/store/sideMenuView';
import { useBadgeStore } from '@/store/badge'
import { useBreakTime } from '../../store/breakTime';
    const badge = useBadgeStore()
    const route = useRoute()
    const auth = useAuthUserStore()
    const sideMenuView = useSideMenuView()
    const props = defineProps(['session', 'auth_user', 'setActiveUser', 'switchLoader'])
    const newsList = ref([])
    const breakTimeStore = useBreakTime()
    onMounted(() => {
        getGlowdNews()
        breakTimeStore.checkBreakTime()          
    })
    
    const todayWeather = computed(() => {
        if(auth.user && auth.user.weathers && auth.user.weathers.value_int !== null){
            return auth.user.weathers.value_int
        }
        return null
    })
    const newsItems = computed(() => {
        if(newsList.value && newsList.value.length){
            let list = [];
            newsList.value.forEach(news => {
                const sourceUrl = news?._embedded?.['wp:featuredmedia']?.[0]?.['media_details']?.['sizes']?.['sidesp']?.['source_url'] || 
                news?._embedded?.['wp:featuredmedia']?.[0]?.['media_details']?.['sizes']?.['thumbnail']?.['source_url'];
                const item  = {
                    title: news.title && news.title.rendered ? news.title.rendered : '',                            
                    src: sourceUrl ? sourceUrl : '',
                    url: news.link ? news.link : ''
                }
                list.push(item)
            });
            return list
        }
        return []
    })
    const selectedRoute = computed(() => {
        return route.name
    })

    const setView = (val) => {
        if(sideMenuView.active !== val && !props.switchLoader){
            sideMenuView.setSideMenuView(val)
        }
    }
    const getGlowdNews = async() => {                
        newsList.value = await fetch('https://news.glowd.co.jp/index.php?rest_route=/wp/v2/posts/&_embed').then(response => response.json())
    }         
    const badgeFilter = (number) => {
        if(number == -1){
            return '1';
        }
        else if(number > 99){
            return '+99';
        }else{
            return number;
        }
    }

</script>
